> I do not think that this is the right way to do that. I think that the property of custom payload should be applied to group not a command, in such case all commands within group would obtain the full payload.

Should we then add an extra parameter `custom_payload` to `mgmt_find_handler`, that will be set the when the correct group is found? Or how would you figure out in `smp_handle_single_payload` if the cbor start- and end byte should be applied?

Something like this;
```c
struct mgmt_group {
	/** Entry list node. */
	sys_snode_t node;

	/** Array of handlers; one entry per command ID. */
	const struct mgmt_handler *mg_handlers;
	uint16_t mg_handlers_count;

	/** The numeric ID of this group. */
	uint16_t mg_group_id;

#if IS_ENABLED(CONFIG_MCUMGR_SMP_SUPPORT_ORIGINAL_PROTOCOL)
	/** A function handler for translating version 2 SMP error codes to version 1 SMP error
	 * codes (optional)
	 */
	smp_translate_error_fn mg_translate_error;
#endif

#if defined(CONFIG_MCUMGR_MGMT_CUSTOM_PAYLOAD)
	bool custom_payload;
#endif
};
```

```c
const struct mgmt_handler *
mgmt_find_handler(uint16_t group_id, uint16_t command_id, bool *custom_payload)     <-----
{
	struct mgmt_group *group = NULL;
	sys_snode_t *snp, *sns;

	/*
	 * Find the group with the specified group id, if one exists
	 * check the handler for the command id and make sure
	 * that is not NULL. If that is not set, look for the group
	 * with a command id that is set
	 */
	SYS_SLIST_FOR_EACH_NODE_SAFE(&mgmt_group_list, snp, sns) {
		struct mgmt_group *loop_group =
			CONTAINER_OF(snp, struct mgmt_group, node);
		if (loop_group->mg_group_id == group_id) {
			if (command_id >= loop_group->mg_handlers_count) {
				break;
			}

			if (!loop_group->mg_handlers[command_id].mh_read &&
				!loop_group->mg_handlers[command_id].mh_write) {
				continue;
			}

			group = loop_group;
			break;
		}
	}

	if (group == NULL) {
		return NULL;
	}
        *custom_payload = group->custom_payload;    <-------
	return &group->mg_handlers[command_id];
}
```

Maybe we could split it up a bit, like;

```c
const struct mgmt_group *
mgmt_find_group(uint16_t group_id)
{
	sys_snode_t *snp, *sns;

	/*
	 * Find the group with the specified group id, if one exists
	 * check the handler for the command id and make sure
	 * that is not NULL. If that is not set, look for the group
	 * with a command id that is set
	 */
	SYS_SLIST_FOR_EACH_NODE_SAFE(&mgmt_group_list, snp, sns) {
		struct mgmt_group *loop_group =
			CONTAINER_OF(snp, struct mgmt_group, node);
		if (loop_group->mg_group_id == group_id) {
			if (command_id >= loop_group->mg_handlers_count) {
				break;
			}

			if (!loop_group->mg_handlers[command_id].mh_read &&
				!loop_group->mg_handlers[command_id].mh_write) {
				continue;
			}

			return loop_group;
		}
	}

	return NULL;
}

const struct mgmt_handler *
mgmt_get_handler(struct mgmt_group *group, uint16_t command_id)
{
	if (group == NULL) {
		return NULL;
	}
	return &group->mg_handlers[command_id];
}
```

